// tenantAtLeadTenant is the tenant "lead.tenant" arrives at.
func (s sinkPairing) tenantAtLeadTenant(ctx context.Context, ref *apptest.RobotRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("lead", "required: it is what says which tenant this belongs to")
	}

	// Asked once a transaction: no step past the first can be repointed, so
	// where this walk arrives from a row is decided until the row is
	// written. See [seen.Tenant].
	return seen.Tenant(s.store.Db.Driver(), "Robot", "tenant", ref, func() ([]byte, error) {
		// The row the edge names, picked the way every other reference is.
		pick, err := bare.RobotPick(ref)
		if err != nil {
			return nil, pderr.At("lead", err)
		}

		k, err := s.store.Db.Robot.Query().Where(pick).QueryTenant().OnlyId(ctx)
		if err != nil {
			// Not there, or more than one -- both are the reference being wrong,
			// and both are the caller's to fix.
			return nil, pderr.Invalidf("lead", "it does not name one row")
		}

		return k[:], nil
	})
}

// tenantAtFollowTenant is the tenant "follow.tenant" arrives at.
func (s sinkPairing) tenantAtFollowTenant(ctx context.Context, ref *apptest.RobotRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("follow", "required: it is what says which tenant this belongs to")
	}

	// Asked once a transaction: no step past the first can be repointed, so
	// where this walk arrives from a row is decided until the row is
	// written. See [seen.Tenant].
	return seen.Tenant(s.store.Db.Driver(), "Robot", "tenant", ref, func() ([]byte, error) {
		// The row the edge names, picked the way every other reference is.
		pick, err := bare.RobotPick(ref)
		if err != nil {
			return nil, pderr.At("follow", err)
		}

		k, err := s.store.Db.Robot.Query().Where(pick).QueryTenant().OnlyId(ctx)
		if err != nil {
			// Not there, or more than one -- both are the reference being wrong,
			// and both are the caller's to fix.
			return nil, pderr.Invalidf("follow", "it does not name one row")
		}

		return k[:], nil
	})
}

// tenancy fills what the schema says this row's tenant is, and refuses a
// row whose other paths do not agree with it.
//
// The request is already this server's copy by the time it arrives, so it
// is written to rather than cloned again.
func (s sinkPairing) tenancy(ctx context.Context, req *apptest.PairingAddRequest) error {
	want, err := s.tenantAtLeadTenant(ctx, req.GetLead())
	if err != nil {
		return err
	}

	if req.HasFollow() {
		got, err := s.tenantAtFollowTenant(ctx, req.GetFollow())
		if err != nil {
			return err
		}
		if string(got) != string(want) {
			// Both exist and both are visible to whoever is writing --
			// the gate already saw to that. What it cannot see is that
			// they are in different tenants, because it asks "may I read
			// this" and a caller who holds several tenants may read both.
			return pderr.Invalidf("follow",
				"it is in another tenant than lead.tenant")
		}
	}

	return nil
}

type sinkReading struct {
	apptest.ReadingServiceServer
	store  bare.Store
	w      *watch.Watch
	namer  slug.Namer
	joined bool
}

func (s Sink) Reading() apptest.ReadingServiceServer {
	v := sinkReading{s.Server.Reading(), s.Server.Store, s.w, s.namer, s.joined}
	v.ReadingServiceServer = bare.ReadingWithAddRule(v.ReadingServiceServer, v.admit)
	return v
}

// admit is what is said of the tenancy of a row an Add of Reading writes:
// it stamps its tenant.
//
// It is asked of an Add and of every item of an AddMany; see [Sink.Reading].
func (s sinkReading) admit(ctx context.Context, req *apptest.ReadingAddRequest) (*apptest.ReadingAddRequest, error) {
	// Copied rather than written to: the request belongs to whoever called,
	// and for a call made in this process that is a message they may still
	// be holding -- a server that changed a caller's own field would be
	// changing a value they can read back.
	r := proto.CloneOf(req)

	if err := s.tenancy(ctx, r); err != nil {
		return nil, err
	}

	return r, nil
}

// Erase forgets what the transaction was told about the row, before it is
// erased: whether a frame may see it, and where a walk from it arrives.
// Neither is true of a row that is gone, nor of another put under its
// key. See [seen.Forget].
func (s sinkReading) Erase(ctx context.Context, req *apptest.ReadingRef) (*apptest.ReadingEraseResponse, error) {
	seen.Forget(s.store.Db.Driver(), "Reading", req)

	return s.ReadingServiceServer.Erase(ctx, req)
}

// Apply forgets what the transaction was told about the row, before it is
// written: a document may move it to a set the caller cannot see. See
// [seen.Forget].
func (s sinkReading) Apply(ctx context.Context, req *apptest.ReadingApplyRequest) (*apptest.Reading, error) {
	seen.Forget(s.store.Db.Driver(), "Reading", req.GetRef())

	return s.ReadingServiceServer.Apply(ctx, req)
}

// Patch forgets what the transaction was told about the row, before it is
// written; see [sinkReading.Apply].
func (s sinkReading) Patch(ctx context.Context, req *apptest.ReadingPatchRequest) (*apptest.Reading, error) {
	seen.Forget(s.store.Db.Driver(), "Reading", req.GetRef())

	return s.ReadingServiceServer.Patch(ctx, req)
}

// tenantAtRobotTenant is the tenant "robot.tenant" arrives at.
func (s sinkReading) tenantAtRobotTenant(ctx context.Context, ref *apptest.RobotRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("robot", "required: it is what says which tenant this belongs to")
	}

	// Asked once a transaction: no step past the first can be repointed, so
	// where this walk arrives from a row is decided until the row is
	// written. See [seen.Tenant].
	return seen.Tenant(s.store.Db.Driver(), "Robot", "tenant", ref, func() ([]byte, error) {
		// The row the edge names, picked the way every other reference is.
		pick, err := bare.RobotPick(ref)
		if err != nil {
			return nil, pderr.At("robot", err)
		}

		k, err := s.store.Db.Robot.Query().Where(pick).QueryTenant().OnlyId(ctx)
		if err != nil {
			// Not there, or more than one -- both are the reference being wrong,
			// and both are the caller's to fix.
			return nil, pderr.Invalidf("robot", "it does not name one row")
		}

		return k[:], nil
	})
}

// tenancy fills what the schema says this row's tenant is, and refuses a
// row whose other paths do not agree with it.
//
// The request is already this server's copy by the time it arrives, so it
// is written to rather than cloned again.
func (s sinkReading) tenancy(ctx context.Context, req *apptest.ReadingAddRequest) error {
	want, err := s.tenantAtRobotTenant(ctx, req.GetRobot())
	if err != nil {
		return err
	}

	// Stamped, whatever the caller said. It is not a field of the request
	// and a caller that reached this server another way does not get to
	// keep what they put there.
	req.SetTenantId(want)

	return nil
}

type sinkRobot struct {
	apptest.RobotServiceServer
	store  bare.Store
	w      *watch.Watch
	namer  slug.Namer
	joined bool
}

func (s Sink) Robot() apptest.RobotServiceServer {
	v := sinkRobot{s.Server.Robot(), s.Server.Store, s.w, s.namer, s.joined}
	v.RobotServiceServer = bare.RobotWithAddRule(v.RobotServiceServer, v.admit)
	return v
}

// admit decides the name of a row an Add of Robot writes, refusing one that
// was given and cannot be one.
//
// It is asked of an Add and of every item of an AddMany; see [Sink.Robot].
//
// The name goes through [Sink.WithNamer], which is unset in most
// deployments and then means: fold what was given, and make a name up
// when nothing was -- for the reason `bare.Minter` makes a key up. An app
// whose rows have to be named says so with `slug.Required`; see
// `slug.Names` for why that is the way round it is.
func (s sinkRobot) admit(ctx context.Context, req *apptest.RobotAddRequest) (*apptest.RobotAddRequest, error) {
	// Copied rather than written to: the request belongs to whoever called,
	// and for a call made in this process that is a message they may still
	// be holding -- a server that changed a caller's own field would be
	// changing a value they can read back.
	r := proto.CloneOf(req)

	v, err := slug.NameWith(ctx, s.namer, "app.Robot", req.GetAlias(), req)
	if err != nil {
		return nil, pderr.At("alias", err)
	}
	r.SetAlias(v)

	return r, nil
}

// Add tries again when the name it made up was taken.
//
// The name is [sinkRobot.admit]'s, and every try goes through it, so a
// name made up is made up again and a name given is the same each time.
func (s sinkRobot) Add(ctx context.Context, req *apptest.RobotAddRequest) (*apptest.Robot, error) {
	// How many names to try. More than one only when the caller named
	// nothing -- then the name is this server's and a collision is this
	// server's to resolve. A name the caller gave is theirs, and quietly
	// choosing a different one would write a row they did not ask for.
	//
	// And only when this Add opens its own transaction; see [Sink.joined].
	tries := 1
	if req.GetAlias() == "" && !s.joined {
		tries = slug.Tries
	}

	for try := 0; ; try++ {
		res, err := s.RobotServiceServer.Add(ctx, req)
		if err == nil || try+1 >= tries || status.Code(err) != codes.AlreadyExists {
			// Whatever it was, said in the words it was said in. Rewriting
			// it into "no free name" would assert the one thing this cannot
			// know -- a duplicate key is the same code -- and would say it
			// loudest exactly when it is wrong.
			return res, err
		}
	}
}

// AddMany tries again, as Add does, when it made up the name of an item and
// the call was refused AlreadyExists -- the whole call, with every name it
// made up made up again, since a refusal of a statement does not say which
// of its rows it was about. A name an item was given is the same each time.
//
// Every name made up is a chance to collide, so a call of many is refused
// more often than an Add of one; `slug.Tries` says how much more.
func (s sinkRobot) AddMany(ctx context.Context, req *apptest.RobotAddManyRequest) (*apptest.RobotAddManyResponse, error) {
	// More than one try only when some item was named by nobody, and only
	// in a transaction of its own; see Add.
	tries := 1
	if !s.joined {
		for _, v := range req.GetItems() {
			if v.GetAlias() == "" {
				tries = slug.Tries
				break
			}
		}
	}

	for try := 0; ; try++ {
		res, err := s.RobotServiceServer.AddMany(ctx, req)
		if err == nil || try+1 >= tries || status.Code(err) != codes.AlreadyExists {
			return res, err
		}
	}
}

// Patch folds a name it was given, and says nothing about one it was not.
//
// The presence is the whole of the difference from [sinkRobot.Add]: a patch
// that does not mention the alias is not a patch setting it to the empty
// string, and refusing one would make every patch of any other field carry
// the name along.
//
// The namer is **not** asked here, and that is the second difference. It
// decides the name of a row being made; a patch that cleared the alias is
// a caller asking for something invalid, and answering that with an
// invented name would hand them a row they did not ask for.
//
// And it forgets what the transaction was told about the row; see
// [sinkRobot.Apply].
func (s sinkRobot) Patch(ctx context.Context, req *apptest.RobotPatchRequest) (*apptest.Robot, error) {
	seen.Forget(s.store.Db.Driver(), "Robot", req.GetRef())

	if !req.HasAlias() {
		return s.RobotServiceServer.Patch(ctx, req)
	}

	v, err := slug.ParseAlias(req.GetAlias())
	if err != nil {
		return nil, pderr.At("alias", err)
	}

	req = proto.CloneOf(req)
	req.SetAlias(v)

	return s.RobotServiceServer.Patch(ctx, req)
}

// Erase forgets what the transaction was told about the row, before it is
// erased: whether a frame may see it, and where a walk from it arrives.
// Neither is true of a row that is gone, nor of another put under its
// key. See [seen.Forget].
func (s sinkRobot) Erase(ctx context.Context, req *apptest.RobotRef) (*apptest.RobotEraseResponse, error) {
	seen.Forget(s.store.Db.Driver(), "Robot", req)

	return s.RobotServiceServer.Erase(ctx, req)
}

// Apply forgets what the transaction was told about the row, before it is
// written: a document may move it to a set the caller cannot see. See
// [seen.Forget].
func (s sinkRobot) Apply(ctx context.Context, req *apptest.RobotApplyRequest) (*apptest.Robot, error) {
	seen.Forget(s.store.Db.Driver(), "Robot", req.GetRef())

	return s.RobotServiceServer.Apply(ctx, req)
}

// orderRobot is how Robots come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderRobot = []sqlpage.Order{
	{Column: robot.FieldDateCreated, Desc: false},
	{Column: robot.FieldId, Desc: false},
}

// orderRobotAlias is the order a request names as ALIAS.
var orderRobotAlias = []sqlpage.Order{
	{Column: robot.FieldAlias, Desc: false},
	{Column: robot.FieldId, Desc: false},
}

// orderRobotAliasDesc is the order a request names as ALIAS_DESC.
var orderRobotAliasDesc = []sqlpage.Order{
	{Column: robot.FieldAlias, Desc: true},
	{Column: robot.FieldId, Desc: false},
}

func afterRobot(v string, by []sqlpage.Order, tag string) (func(*sql.Selector), error) {
	var (
		at0 time.Time
		at1 uuid.UUID
	)
	if err := pdAfter(v, tag, &at0, &at1); err != nil {
		return nil, err
	}

	return sqlpage.After(by, []any{at0, at1})
}

func nextRobot(last *ent.Robot, tag string) (string, error) {
	return pdNext(tag, last.DateCreated, last.Id)
}

func afterRobotAlias(v string, by []sqlpage.Order, tag string) (func(*sql.Selector), error) {
	var (
		at0 string
		at1 uuid.UUID
	)
	if err := pdAfter(v, tag, &at0, &at1); err != nil {
		return nil, err
	}

	return sqlpage.After(by, []any{at0, at1})
}

func nextRobotAlias(last *ent.Robot, tag string) (string, error) {
	return pdNext(tag, last.Alias, last.Id)
}

func afterRobotAliasDesc(v string, by []sqlpage.Order, tag string) (func(*sql.Selector), error) {
	var (
		at0 string
		at1 uuid.UUID
	)
	if err := pdAfter(v, tag, &at0, &at1); err != nil {
		return nil, err
	}

	return sqlpage.After(by, []any{at0, at1})
}

func nextRobotAliasDesc(last *ent.Robot, tag string) (string, error) {
	return pdNext(tag, last.Alias, last.Id)
}

// orderByRobot is an order as ent orders a query by it.
func orderByRobot(by []sqlpage.Order) []robot.OrderOption {
	out := make([]robot.OrderOption, len(by))
	for i, o := range by {
		if o.Desc {
			out[i] = sql.OrderByField(o.Column, sql.OrderDesc()).ToFunc()
			continue
		}

		out[i] = sql.OrderByField(o.Column).ToFunc()
	}

	return out
}

const (
	// RobotPageSize is what a request that did not say gets, and
	// RobotPageLimit is the most it gets however loudly it asks.
	RobotPageSize  = 50
	RobotPageLimit = 100

	// RobotFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	RobotFilterLimit = 32
)

// List answers with the Robots that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkRobot) List(ctx context.Context, req *apptest.RobotListRequest) (*apptest.RobotListResponse, error) {
	q := s.store.Db.Robot.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.RobotNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > RobotFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), RobotFilterLimit)
		}

		ps := make([]predicate.Robot, 0, len(fs))
		for i, f := range fs {
			p, err := filterRobot(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(robot.Or(ps...))
	}

	// Which order, and which way: one the schema declared, and never one a
	// request makes up, since an order is a walk of an index.
	by, after, next, tag := orderRobot, afterRobot, nextRobot, ""
	switch req.GetOrder() {
	case apptest.RobotListOrder_ROBOT_LIST_ORDER_UNSPECIFIED:
	case apptest.RobotListOrder_ROBOT_LIST_ORDER_ALIAS:
		by, after, next, tag = orderRobotAlias, afterRobotAlias, nextRobotAlias, "alias"
	case apptest.RobotListOrder_ROBOT_LIST_ORDER_ALIAS_DESC:
		by, after, next, tag = orderRobotAliasDesc, afterRobotAliasDesc, nextRobotAliasDesc, "alias_desc"
	default:
		return nil, status.Errorf(codes.InvalidArgument, "order: %v is not an order this list is read in", req.GetOrder())
	}
	if req.GetReverse() {
		// The same index, walked from the other end.
		by, tag = pdReverse(by), tag+"/reverse"
	}

	if v := req.GetAfter(); v != "" {
		p, err := after(v, by, tag)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	q.WithTenant()

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), RobotPageSize, RobotPageLimit)
	us, err := q.Order(orderByRobot(by)...).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*apptest.Robot, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := apptest.RobotListResponse_builder{Items: items}.Build()
	if more {
		v, err := next(us[len(us)-1], tag)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(v)
	}

	return res, nil
}

// filterRobot turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterRobot(f *apptest.RobotFilter) (predicate.Robot, error) {
	ps := make([]predicate.Robot, 0, 1)
	if f.HasRef() {
		p, err := bare.RobotPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasTenant() {
		w := f.GetTenant()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "tenant: %s", err)
			}

			ps = append(ps, robot.TenantIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.TenantPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, robot.HasTenantWith(q))
		}
	}
	if f.HasThing() {
		w := f.GetThing()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "thing: %s", err)
			}

			ps = append(ps, robot.ThingIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.ThingPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, robot.HasThingWith(q))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return robot.And(ps...), nil
}

// RobotService is the prefix of every Rpc of that service, which is how a
// change is known to be about a Robot. A service is named for the entity it
// is about, so the name carries it.
var RobotService = watch.ServiceOf(apptest.RobotService_Get_FullMethodName)

// Watch answers with the Robots this caller may see, as they are now and as
// they change.
//
// What is sent is **state and never a delta**, which is what makes a stream
// that missed something still correct: the next item about a row carries the
// whole of it, so a client converges rather than replays. It is also what
// makes the first message safe to duplicate against the ones after it.
func (s sinkRobot) Watch(req *apptest.RobotWatchRequest, out grpc.ServerStreamingServer[apptest.RobotWatchResponse]) error {
	ctx := out.Context()

	// A watch with no filters is the whole table, forever. It is the one
	// shape that has no cap at all, so it is the one shape refused.
	fs := req.GetFilters()
	switch {
	case len(fs) == 0:
		return status.Error(codes.InvalidArgument,
			"filters: a watch says which rows it is about; one that says nothing is the whole table, for as long as it is open")
	case len(fs) > RobotFilterLimit:
		return status.Errorf(codes.InvalidArgument,
			"filters: %d of them, and %d is the most one watch carries", len(fs), RobotFilterLimit)
	}

	// Resolved before anything is subscribed to, so a name that names
	// nothing is an answer rather than a stream that quietly watches none.
	watching, err := s.watchRobotKeys(ctx, fs)
	if err != nil {
		return err
	}

	var snapshot func(watch.Seen) error
	if !req.GetSkipSnapshot() {
		snapshot = func(sent watch.Seen) error { return s.watchNow(ctx, req, out, sent) }
	}

	if s.w == nil {
		return status.Error(codes.Unimplemented,
			"this deployment publishes no changes; see WithWatch")
	}

	return watch.Stream(ctx, s.w, RobotService, snapshot,
		func(ks map[pdid.Id]string, sent watch.Seen) error {
			items := make([]*apptest.RobotWatchItem, 0, len(ks))
			for k, action := range ks {
				u, err := s.watchRead(ctx, watching, k)
				if err != nil {
					return err
				}
				if u == nil && !sent[k] {
					// Not theirs, or not what they asked for, and they
					// have never been told about it. A row that never
					// matched is not news.
					continue
				}

				sent[k] = u != nil
				items = append(items, apptest.RobotWatchItem_builder{
					Id:     k.Bytes(),
					Value:  u,
					Action: action,
				}.Build())
			}
			if len(items) == 0 {
				return nil
			}

			return out.Send(apptest.RobotWatchResponse_builder{Items: items}.Build())
		})
}

// watchNow sends what matches right now, through the same List a caller
// would have called -- so what a stream begins with and what a list answers
// cannot disagree, and a client does not have to do both and race them.
func (s sinkRobot) watchNow(
	ctx context.Context, req *apptest.RobotWatchRequest, out grpc.ServerStreamingServer[apptest.RobotWatchResponse],
	sent watch.Seen,
) error {
	after := ""
	for {
		res, err := s.List(ctx, apptest.RobotListRequest_builder{
			Filters: req.GetFilters(),
			After:   after,
		}.Build())
		if err != nil {
			return err
		}

		items := make([]*apptest.RobotWatchItem, 0, len(res.GetItems()))
		for _, u := range res.GetItems() {
			k, err := pdid.From(u.GetId())
			if err != nil {
				return err
			}

			sent[k] = true
			// No action: this is not something anybody asked for, it is
			// what is already there.
			items = append(items, apptest.RobotWatchItem_builder{Id: u.GetId(), Value: u}.Build())
		}
		if len(items) > 0 {
			if err := out.Send(apptest.RobotWatchResponse_builder{Items: items}.Build()); err != nil {
				return err
			}
		}

		if after = res.GetNext(); after == "" {
			return nil
		}
	}
}

// watchRead answers with the row as it is now, or nil when it is no longer
// one this caller may see -- erased, walled off, or no longer matching what
// they asked for. The three are deliberately indistinguishable to a caller:
// a stream that told them apart would be saying which rows stopped being
// theirs, which is the thing the wall is for.
//
// The Get is what keeps the wall out of this file. It goes through the same
// server every other read does, with the context of the caller who asked, so
// a row they may not see comes back NotFound and is never sent.
func (s sinkRobot) watchRead(
	ctx context.Context, watching []pdid.Id, k pdid.Id,
) (*apptest.Robot, error) {
	// Not one of the rows this stream is about. Asked before the read, so a
	// busy table costs a stream nothing for the rows it does not watch.
	if !slices.Contains(watching, k) {
		return nil, nil
	}

	v, err := s.Get(ctx, apptest.RobotGetRequest_builder{
		Ref: apptest.RobotRef_builder{Id: k.Bytes()}.Build(),
	}.Build())
	if err != nil {
		if status.Code(err) == codes.NotFound {
			return nil, nil
		}

		return nil, err
	}

	return v, nil
}

// watchRobotKeys is the rows a stream is about, resolved once when it opens.
//
// A filter names a row and a row is named several ways -- by identifier, or
// by whatever unique index the schema declared. Resolving them here rather
// than comparing them per event does three things: the comparison afterwards
// is an identifier against an identifier, a name that names nothing is
// refused when the stream opens rather than silently watching nothing, and a
// row renamed while the stream is open goes on being the row that was asked
// for -- which is what somebody watching a thing meant.
func (s sinkRobot) watchRobotKeys(
	ctx context.Context, fs []*apptest.RobotFilter,
) ([]pdid.Id, error) {
	ks := make([]pdid.Id, 0, len(fs))
	for i, f := range fs {
		if !f.HasRef() {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters[%d]: a watch says which rows it is about by naming them", i)
		}

		v, err := s.Get(ctx, apptest.RobotGetRequest_builder{Ref: f.GetRef()}.Build())
		if err != nil {
			return nil, err
		}

		k, err := pdid.From(v.GetId())
		if err != nil {
			return nil, err
		}

		ks = append(ks, k)
	}

	return ks, nil
}

