// WatchRecorder answers with the recorder that remembers a write for `w`.
//
// It is the other end of the hook the trail hangs off, and it wants the
// opposite thing from that moment: a trail row has to hold or fall with the
// write, so it is written there and then; an event has to be published only
// if the write survived, so nothing is published here at all.
//
//	sink, err := pd.NewSink(db, bare.WithRecorder(pd.WatchRecorder(w)))
func WatchRecorder(w *watch.Watch) bare.Recorder {
	return watchRecorder{w}
}

type watchRecorder struct {
	w *watch.Watch
}

var _ bare.Recorder = watchRecorder{}

func (r watchRecorder) Record(ctx context.Context, _ bare.Server, c bare.Change) error {
	k, err := pdid.From(keyBytes(c.Key))
	if err != nil {
		// A key this app does not make. Nothing to publish about it, and
		// nothing worth failing a write for.
		return nil
	}

	var doc []byte
	if v := hidden(k, c.Patch); v != nil {
		if b, err := proto.Marshal(v); err == nil {
			doc = b
		}
	}

	r.w.Note(ctx, watch.Change{
		Method: c.Method,
		By:     c.By,
		Key:    k,
		Patch:  doc,
	})

	return nil
}

// keyBytes is a key as the sixteen bytes an identifier is.
func keyBytes(v any) []byte {
	switch u := v.(type) {
	case uuid.UUID:
		return u[:]
	case [16]byte:
		return u[:]
	}

	return nil
}

// OutboxRecorder answers with the recorder that writes each write to the
// queue, inside the transaction that makes it.
//
// It is what makes an event survive a process that stops between the commit
// and the publish. `WatchRecorder` remembers in memory and an interceptor
// publishes once the handler has answered; this writes a row, and [Drain]
// publishes it whenever somebody next gets round to it -- which may be after
// a restart, and that is the whole of the point.
//
// Both, for a deployment that wants both: the first is immediate and lossy,
// the second is durable and late. A subscriber sees the same row twice and
// the second time says what the first said, since what is sent is state.
//
//	sink, err := pd.NewSink(db, bare.WithRecorder(pd.OutboxRecorder()))
func OutboxRecorder() bare.Recorder { return outboxRecorder{} }

type outboxRecorder struct{}

var _ bare.Recorder = outboxRecorder{}

// Record writes the row.
//
// Unlike the watch recorder it **refuses** when it cannot, which is the
// difference between the two in one line: this exists so that an event is
// not lost, and letting a write commit whose event could not be queued would
// lose exactly the one it was written to keep.
//
// It writes through `s.Db`, which is the client this transaction is running
// on, and not through a server: there are no Rpcs on this entity, on
// purpose -- see the note in payday's outbox.proto.
func (outboxRecorder) Record(ctx context.Context, s bare.Server, c bare.Change) error {
	k, err := pdid.From(keyBytes(c.Key))
	if err != nil {
		// A key this app does not make, so there is nothing an identifier
		// could say about it and nobody could act on the event.
		return nil
	}

	doc := []byte{}
	if v := hidden(k, c.Patch); v != nil {
		b, err := proto.Marshal(v)
		if err != nil {
			return err
		}

		doc = b
	}

	var actor, tenant pdid.Id
	if f, ok := frame.From(ctx); ok {
		actor = f.Actor
		tenant = f.Tenant
	}

	return s.Db.Outbox.Create().
		SetId(pdid.New(OutboxDomain).Uuid()).
		SetTenantId(tenant.Uuid()).
		SetActorId(actor.Uuid()).
		SetMethod(c.Method).
		SetBy(c.By).
		SetObjectId(k.Uuid()).
		SetPatch(doc).
		Exec(ctx)
}

// DrainSize is how many rows one pass takes.
//
// Bounded because a queue that has been building since a broker went down is
// exactly when a pass must not try to hold all of it, and small enough that
// a pass which fails republishes little.
const DrainSize = 256

// Drain answers with the loop that publishes what the queue holds and takes
// it away.
//
// It is a [spin.Spinner], so it is handed to `spin.Run` with the stack:
//
//	go spin.Run(ctx, slices.Values([]any{pd.Drain(db, broker, time.Second)}))
//
// # It publishes before it deletes
//
// Which is the order that gives at-least-once, and the other order gives
// at-most-once. A process that stops between the two publishes those rows
// again on the next pass, and a subscriber reads the same state twice -- the
// second saying what the first said. That is only harmless because what
// travels is state and not a delta, and it is why an outbox is a table and a
// loop here rather than a project.
//
// # Under a lease, one replica drains
//
// It is `payday.outbox`, and takes no lock of its own. Under `spin.WithLease`
// -- `spin.lease: postgres` -- one process of a deployment runs it; without a
// lease every process does, and two of these drain the same rows and publish
// them each. By the paragraph above neither is a correctness problem, which
// matters since even under a lease two may drain at once around a failover:
// what the lease saves is the work, and a subscriber reading each state twice.
func Drain(db *ent.Client, b watch.Broker, every time.Duration) spin.Spinner {
	return drain{db, b, every}
}

type drain struct {
	db    *ent.Client
	b     watch.Broker
	every time.Duration
}

var _ spin.Spinner = drain{}
var _ spin.Named = drain{}

func (drain) SpinName() string { return "payday.outbox" }

func (d drain) Spin(ctx context.Context) error {
	return spin.Every(d.every, d.pass)(ctx)
}

// pass takes one batch, and keeps taking them for as long as it finds a full
// one -- otherwise a queue of ten thousand drains at one batch per tick and
// takes an hour to catch up from a minute of trouble.
//
// It answers nil for a failure rather than ending the loop, and logs it. A
// broker that is down or a database that blinked is a thing to try again;
// giving up would take the process down and stop serving requests that were
// fine. See the note on failure in `payday/spin` -- the loud direction is the
// default there, and this is one of the cases that means the other.
func (d drain) pass(ctx context.Context) error {
	for {
		n, err := d.once(ctx)
		if err != nil {
			log.From(ctx).ErrorContext(ctx, "outbox", slog.Any("err", err))
			return nil
		}
		if n < DrainSize {
			return nil
		}
		if ctx.Err() != nil {
			return nil
		}
	}
}

// once publishes one batch and answers with how many rows were in it.
func (d drain) once(ctx context.Context) (int, error) {
	// Oldest first, which is the order they were written in: an identifier
	// carries the millisecond it was minted and a sequence within it, so the
	// key **is** the order and there is no column to keep in step.
	vs, err := d.db.Outbox.Query().
		Order(outbox.ById()).
		Limit(DrainSize).
		All(ctx)
	if err != nil {
		return 0, err
	}
	if len(vs) == 0 {
		return 0, nil
	}

	ks := make([]uuid.UUID, len(vs))
	for i, v := range vs {
		ks[i] = v.Id
		var resource *pdpb.WatchEvent
		call := v.Method
		if v.Event != nil && len(*v.Event) > 0 {
			resource = &pdpb.WatchEvent{}
			if err := proto.Unmarshal(*v.Event, resource); err != nil {
				return 0, err
			}
			call = resource.GetCallMethod()
		}
		if err := watch.Confirm(ctx, d.b, watch.Event{
			Actor:  pdid.Id(v.ActorId),
			Tenant: pdid.Id(v.TenantId),
			Method: call,
			Changes: []watch.Change{{
				Method:   v.Method,
				By:       v.By,
				Key:      pdid.Id(v.ObjectId),
				Patch:    v.Patch,
				Resource: resource,
			}},
		}); err != nil {
			return 0, err
		}
	}

	// And only then. A row deleted before it was published is an event that
	// nothing will ever say again.
	if _, err := d.db.Outbox.Delete().
		Where(outbox.IdIn(ks...)).
		Exec(ctx); err != nil {
		return 0, err
	}

	return len(vs), nil
}

// TrailStore is the audit table as [trail.Store] sees it.
//
// Handed to `trail.Sweep` beside a policy, and to whatever command an app
// gives an operator:
//
//	s.Spin = append(s.Spin, trail.Sweep(pd.TrailStore(db), policy))
func TrailStore(db *ent.Client) trail.Store {
	return trailStore{db}
}

type trailStore struct{ db *ent.Client }

var _ trail.Store = trailStore{}

// of narrows to the kinds a read is about, and to whose rows they are.
//
// By the `domain` column and not by the domain byte inside `object_id`,
// which carries the same fact and cannot be indexed: *what kind was this
// row about* is answered by reading a row, and *which rows were about
// robots* is a query over a set. The second is what a retention policy is
// made of.
//
// And by the three tenant columns, which are what the wall on the trail
// reads: a row is readable by every tenant it names, and so it is on each
// of their windows.
func (s trailStore) of(k trail.Scope) *ent.AuditQuery {
	q := s.db.Audit.Query()
	if len(k.Only) > 0 {
		q = q.Where(audit.DomainIn(numbers(k.Only)...))
	} else if len(k.Except) > 0 {
		q = q.Where(audit.DomainNotIn(numbers(k.Except)...))
	}

	if len(k.Objects) > 0 {
		ids := make([]uuid.UUID, len(k.Objects))
		for i, v := range k.Objects {
			ids[i] = v.Uuid()
		}

		q = q.Where(audit.ObjectIdIn(ids...))
	}

	t := k.Tenant.Uuid()
	switch k.Whose {
	case trail.FiledUnder:
		q = q.Where(audit.TenantIdEQ(t))
	case trail.Alone:
		q = q.Where(trailAlone(t))
	case trail.Together:
		q = q.Where(
			audit.Or(audit.TenantIdEQ(t), audit.ActorTenantIdEQ(t), audit.CounterpartTenantIdEQ(t)),
			audit.Not(trailAlone(t)),
		)
	case trail.Sharing:
		q = q.Where(audit.TenantIdEQ(t), audit.Not(trailAlone(t)))
	}

	return q
}

// trailAlone is a row filed under `t` that names no other tenant: the actor
// is of `t` or is nobody, and so is the other party if there is one. Nobody
// is the zero identifier -- the deployment, writing to itself.
func trailAlone(t uuid.UUID) predicate.Audit {
	none := uuid.Nil()

	return audit.And(
		audit.TenantIdEQ(t),
		audit.ActorTenantIdIn(t, none),
		audit.Or(audit.CounterpartTenantIdIsNil(), audit.CounterpartTenantIdIn(t, none)),
	)
}

// Tenants is one seek per tenant: the next `tenant_id` after the last, which
// the index on `(tenant_id, date_created)` answers without reading the rows
// in between. A `DISTINCT` would read all of them.
func (s trailStore) Tenants(ctx context.Context, after pdid.Id, limit int) ([]pdid.Id, error) {
	out := []pdid.Id{}
	last := after.Uuid()
	for len(out) < limit {
		next, found := uuid.Nil(), false
		v, err := s.db.Audit.Query().
			Where(audit.TenantIdGT(last)).
			Order(ent.Asc(audit.FieldTenantId)).
			First(ctx)
		switch {
		case err == nil:
			next, found = v.TenantId, true
		case !ent.IsNotFound(err):
			return out, err
		}
		w, err := s.db.Access.Query().
			Where(access.TenantIdGT(last)).
			Order(ent.Asc(access.FieldTenantId)).
			First(ctx)
		switch {
		case err == nil && (!found || w.TenantId.Compare(next) < 0):
			next, found = w.TenantId, true
		case err != nil && !ent.IsNotFound(err):
			return out, err
		}
		if !found {
			break
		}

		out = append(out, pdid.Id(next))
		last = next
	}

	return out, nil
}

// older is a scope's rows written before `at`, past `after`, oldest first.
func (s trailStore) older(k trail.Scope, at time.Time, after trail.Cursor, limit int) (*ent.AuditQuery, error) {
	q := s.of(k).Where(audit.DateCreatedLT(at))
	if after.Key != nil {
		id, err := cursorOf(after.Key)
		if err != nil {
			return nil, err
		}

		// After the cursor, as one comparison of the pair: an index starts the read
		// at it, where the OR it means is a filter and every page is read from the
		// first row.
		q = q.Where(func(s *sql.Selector) {
			s.Where(sql.CompositeGT([]string{s.C(audit.FieldDateCreated), s.C(audit.FieldId)}, after.Created, id))
		})
	}

	return q.
		Order(ent.Asc(audit.FieldDateCreated, audit.FieldId)).
		Limit(limit), nil
}

func (s trailStore) Older(ctx context.Context, k trail.Scope, at time.Time, after trail.Cursor, limit int) (trail.Rows, error) {
	q, err := s.older(k, at, after, limit)
	if err != nil {
		return nil, err
	}

	vs, err := q.All(ctx)
	if err != nil {
		return nil, err
	}

	out := make(trail.Rows, 0, len(vs))
	for _, v := range vs {
		b, err := protojson.Marshal(v.Proto())
		if err != nil {
			return nil, err
		}

		out = append(out, trail.Row{
			Doc:     b,
			Key:     v.Id,
			Domain:  pdid.Domain(v.Domain),
			Created: v.DateCreated,
			Tenants: trail.TenantsOf(v.TenantId, v.ActorTenantId, v.CounterpartTenantId),
		})
	}

	b, err := s.accessRows(ctx, k, at, after, limit, true)
	if err != nil {
		return nil, err
	}

	return mergeRows(out, b, limit), nil
}

// Heads is the same rows with only what a decision about them reads: no
// `value`, no `patch`, and nothing marshalled.
func (s trailStore) Heads(ctx context.Context, k trail.Scope, at time.Time, after trail.Cursor, limit int) (trail.Rows, error) {
	q, err := s.older(k, at, after, limit)
	if err != nil {
		return nil, err
	}

	vs, err := q.Select(
		audit.FieldId,
		audit.FieldDateCreated,
		audit.FieldDomain,
		audit.FieldTenantId,
		audit.FieldActorTenantId,
		audit.FieldCounterpartTenantId,
	).All(ctx)
	if err != nil {
		return nil, err
	}

	out := make(trail.Rows, 0, len(vs))
	for _, v := range vs {
		out = append(out, trail.Row{
			Key:     v.Id,
			Domain:  pdid.Domain(v.Domain),
			Created: v.DateCreated,
			Tenants: trail.TenantsOf(v.TenantId, v.ActorTenantId, v.CounterpartTenantId),
		})
	}

	b, err := s.accessRows(ctx, k, at, after, limit, false)
	if err != nil {
		return nil, err
	}

	return mergeRows(out, b, limit), nil
}

func (s trailStore) Count(ctx context.Context, k trail.Scope, at time.Time) (int, error) {
	n, err := s.of(k).Where(audit.DateCreatedLT(at)).Count(ctx)
	if err != nil {
		return n, err
	}
	if q := s.accessOf(k); q != nil {
		m, err := q.Where(access.DateCreatedLT(at)).Count(ctx)
		return n + m, err
	}

	return n, nil
}

// Forget removes exactly the rows these keys name.
//
// By identifier and not by the cutoff again, which is the whole of what
// makes the archive trustworthy: a second query matches whatever is true
// when it runs, and a row backdated by a clock that stepped is one it
// removes and the archive does not have.
func (s trailStore) Forget(ctx context.Context, keys []any) (int, error) {
	ids, accessed, err := trailKeys(keys)
	if err != nil {
		return 0, err
	}

	n, err := s.db.Audit.Delete().Where(audit.IdIn(ids...)).Exec(ctx)
	if err != nil || len(accessed) == 0 {
		return n, err
	}

	m, err := s.db.Access.Delete().Where(access.IdIn(accessed...)).Exec(ctx)
	return n + m, err
}

// Blank empties the two columns that hold contents, for exactly these rows.
//
// Empty and not nil: nil is SQL NULL, which a NOT NULL column refuses on
// PostgreSQL and accepts on SQLite.
func (s trailStore) Blank(ctx context.Context, keys []any) (int, error) {
	ids, accessed, err := trailKeys(keys)
	if err != nil {
		return 0, err
	}

	n, err := s.db.Audit.Update().
		Where(audit.IdIn(ids...)).
		SetValue([]byte{}).
		SetPatch([]byte{}).
		Save(ctx)
	if err != nil || len(accessed) == 0 {
		return n, err
	}

	m, err := s.db.Access.Update().Where(access.IdIn(accessed...)).SetValue([]byte{}).Save(ctx)
	return n + m, err
}

// trailKeys is the keys this store gave out, back as what each table deletes
// by: the trail's, and the access record's.
func trailKeys(keys []any) (trailed, accessed []uuid.UUID, err error) {
	for _, k := range keys {
		switch v := k.(type) {
		case uuid.UUID:
			trailed = append(trailed, v)
		case accessKey:
			accessed = append(accessed, uuid.UUID(v))
		default:
			return nil, nil, fmt.Errorf("trail: %T is not a key this store gave out", k)
		}
	}

	return trailed, accessed, nil
}

// cursorOf is the identifier a key this store gave out holds, which is what
// a read carries on from in either table: both order by when a row was
// written, then by its identifier.
func cursorOf(k any) (uuid.UUID, error) {
	switch v := k.(type) {
	case uuid.UUID:
		return v, nil
	case accessKey:
		return uuid.UUID(v), nil
	}

	return uuid.Nil(), fmt.Errorf("trail: %T is not a key this store gave out", k)
}

// accessKey is the key of a row of the access record, as this store gives
// it out: a type of its own, so that what deletes by it deletes from the
// table it is of.
type accessKey uuid.UUID

// accessOf narrows the access record to a scope, and is nil for a scope that
// is not about its kind, or that is about objects: an access row is about
// none.
func (s trailStore) accessOf(k trail.Scope) *ent.AccessQuery {
	if !k.Has(AccessDomain) || len(k.Objects) > 0 {
		return nil
	}

	q := s.db.Access.Query()
	t := k.Tenant.Uuid()
	switch k.Whose {
	case trail.FiledUnder:
		q = q.Where(access.TenantIdEQ(t))
	case trail.Alone:
		q = q.Where(accessAlone(t))
	case trail.Together:
		q = q.Where(access.Or(access.TenantIdEQ(t), access.ActorTenantIdEQ(t)), access.Not(accessAlone(t)))
	case trail.Sharing:
		q = q.Where(access.TenantIdEQ(t), access.Not(accessAlone(t)))
	}

	return q
}

// accessAlone is an access row filed under `t` that names no other tenant:
// the caller is of `t`, or is nobody.
func accessAlone(t uuid.UUID) predicate.Access {
	return access.And(access.TenantIdEQ(t), access.ActorTenantIdIn(t, uuid.Nil()))
}

// accessRows is the access record's rows of a scope written before `at`,
// past `after`, oldest first: what Older and Heads merge with the trail's.
// With `docs`, each as the document the archive keeps.
func (s trailStore) accessRows(ctx context.Context, k trail.Scope, at time.Time, after trail.Cursor, limit int, docs bool) (trail.Rows, error) {
	q := s.accessOf(k)
	if q == nil {
		return nil, nil
	}

	q = q.Where(access.DateCreatedLT(at))
	if after.Key != nil {
		id, err := cursorOf(after.Key)
		if err != nil {
			return nil, err
		}

		// After the cursor, as one comparison of the pair: an index starts the read
		// at it, where the OR it means is a filter and every page is read from the
		// first row.
		q = q.Where(func(s *sql.Selector) {
			s.Where(sql.CompositeGT([]string{s.C(access.FieldDateCreated), s.C(access.FieldId)}, after.Created, id))
		})
	}
	q = q.Order(ent.Asc(access.FieldDateCreated, access.FieldId)).Limit(limit)
	if !docs {
		q = q.Select(access.FieldId, access.FieldDateCreated, access.FieldTenantId, access.FieldActorTenantId).AccessQuery
	}

	vs, err := q.All(ctx)
	if err != nil {
		return nil, err
	}

	out := make(trail.Rows, 0, len(vs))
	for _, v := range vs {
		r := trail.Row{
			Key:     accessKey(v.Id),
			Domain:  AccessDomain,
			Created: v.DateCreated,
			Tenants: trail.TenantsOf(v.TenantId, v.ActorTenantId, nil),
		}
		if docs {
			b, err := protojson.Marshal(v.Proto())
			if err != nil {
				return nil, err
			}
			r.Doc = b
		}

		out = append(out, r)
	}

	return out, nil
}

// mergeRows is two tables' oldest rows as one batch, in the order each was
// read in, and at most `limit` of them.
func mergeRows(a, b trail.Rows, limit int) trail.Rows {
	out := make(trail.Rows, 0, min(len(a)+len(b), limit))
	for len(out) < limit && (len(a) > 0 || len(b) > 0) {
		if len(b) == 0 || (len(a) > 0 && rowBefore(a[0], b[0])) {
			out = append(out, a[0])
			a = a[1:]
			continue
		}

		out = append(out, b[0])
		b = b[1:]
	}

	return out
}

// rowBefore answers whether `a` was written before `b`, by the order a pass
// reads in: when, then the identifier.
func rowBefore(a, b trail.Row) bool {
	if c := a.Created.Compare(b.Created); c != 0 {
		return c < 0
	}

	x, _ := cursorOf(a.Key)
	y, _ := cursorOf(b.Key)
	return x.Compare(y) < 0
}

// numbers is what the column holds, which is a domain widened to what
// protobuf has: there is no `uint8`.
func numbers(ds []pdid.Domain) []uint32 {
	out := make([]uint32, len(ds))
	for i, d := range ds {
		out[i] = uint32(d)
	}

	return out
}

// archivedCounter is the manifest's one row that is not a blob: the number
// of the latest checkpoint, whose row lock is what keeps two checkpoints
// from taking one number.
var archivedCounter = uuid.Nil()

func (s trailStore) Adding(ctx context.Context, ns, intent string, labels map[string]string, sign trail.Sign) (any, error) {
	id := pdid.New(ArchivedDomain).Uuid()
	sig, err := sign(trail.Archived{}, trail.Archived{Key: id, Namespace: ns, Intent: intent, Labels: labels, State: trail.Adding})
	if err != nil {
		return nil, err
	}

	v, err := s.db.Archived.Create().
		SetId(id).
		SetNamespace(ns).
		SetDigest("").
		SetIntent(intent).
		SetLabels(labels).
		SetState(trail.Adding).
		SetSince(0).
		SetGone(0).
		SetSignature(sig.Sig).
		SetSignedBy(sig.Key).
		SetDateUpdated(time.Now()).
		Save(ctx)
	if err != nil {
		return nil, err
	}

	return v.Id, nil
}

func (s trailStore) Added(ctx context.Context, key any, digest string, labels map[string]string, sign trail.Sign) error {
	id, ok := key.(uuid.UUID)
	if !ok {
		return fmt.Errorf("trail: %T is not a key this store gave out", key)
	}

	v, err := s.db.Archived.Get(ctx, id)
	if err != nil {
		return err
	}

	was := archivedRow(v)
	is := was
	is.Digest, is.Labels, is.State = digest, labels, trail.Present

	return s.archivedWrite(ctx, id, was, is, sign)
}

func (s trailStore) Drop(ctx context.Context, key any) error {
	id, ok := key.(uuid.UUID)
	if !ok {
		return fmt.Errorf("trail: %T is not a key this store gave out", key)
	}

	_, err := s.db.Archived.Delete().Where(archived.IdEQ(id), archived.StateEQ(trail.Adding)).Exec(ctx)
	return err
}

// Mark is a row at a time, each signed as it is about to be.
func (s trailStore) Mark(ctx context.Context, ns, digest, from, to string, sign trail.Sign) error {
	vs, err := s.db.Archived.Query().
		Where(archived.NamespaceEQ(ns), archived.DigestEQ(digest), archived.StateEQ(from)).
		All(ctx)
	if err != nil {
		return err
	}

	for _, v := range vs {
		was := archivedRow(v)
		is := was
		is.State = to
		if err := s.archivedWrite(ctx, v.Id, was, is, sign); err != nil {
			return err
		}
	}

	return nil
}

func (s trailStore) Label(ctx context.Context, ns, digest string, labels map[string]string, sign trail.Sign) error {
	vs, err := s.db.Archived.Query().
		Where(archived.NamespaceEQ(ns), archived.DigestEQ(digest), archived.StateNEQ(trail.Erased)).
		All(ctx)
	if err != nil {
		return err
	}

	for _, v := range vs {
		was := archivedRow(v)
		is := was
		is.Labels = labels
		if err := s.archivedWrite(ctx, v.Id, was, is, sign); err != nil {
			return err
		}
	}

	return nil
}

// archivedWrite writes one row whole -- every field its signature is over,
// and the signature -- so that what a row says is what was signed, whichever
// of two writers is last. Only while the row is still in the state it was
// read in: one another act moved meanwhile is that act's.
func (s trailStore) archivedWrite(ctx context.Context, id uuid.UUID, was, is trail.Archived, sign trail.Sign) error {
	sig, err := sign(was, is)
	if err != nil {
		return err
	}

	_, err = s.db.Archived.Update().
		Where(archived.IdEQ(id), archived.StateEQ(was.State)).
		SetDigest(is.Digest).
		SetLabels(is.Labels).
		SetState(is.State).
		SetSignature(sig.Sig).
		SetSignedBy(sig.Key).
		SetDateUpdated(time.Now()).
		Save(ctx)
	return err
}

func (s trailStore) Rows(ctx context.Context) ([]trail.Archived, error) {
	vs, err := s.db.Archived.Query().
		Where(archived.NamespaceNEQ(""), archived.StateNEQ(trail.Erased)).
		All(ctx)
	if err != nil {
		return nil, err
	}

	return archivedRows(vs), nil
}

// Checkpoint is one transaction, and the counter's row is the first thing it
// writes: a second checkpoint waits on that row until the first has
// committed, and then takes the next number.
func (s trailStore) Checkpoint(ctx context.Context, after int) (int, []trail.Archived, error) {
	tx, err := s.db.Tx(ctx)
	if err != nil {
		return 0, nil, err
	}
	defer tx.Rollback()

	n, err := tx.Archived.Update().Where(archived.IdEQ(archivedCounter)).AddSince(1).SetDateUpdated(time.Now()).Save(ctx)
	if err != nil {
		return 0, nil, err
	}
	if n == 0 {
		// The first. Two at once both try, and one is refused for the key.
		if err := tx.Archived.Create().
			SetId(archivedCounter).
			SetNamespace("").
			SetDigest("").
			SetIntent("").
			SetLabels(map[string]string{}).
			SetState("counter").
			SetSince(1).
			SetGone(0).
			SetDateUpdated(time.Now()).
			Exec(ctx); err != nil {
			return 0, nil, err
		}
	}

	c, err := tx.Archived.Get(ctx, archivedCounter)
	if err != nil {
		return 0, nil, err
	}
	k := c.Since

	// Past `after` as well: an acceptance of a database restored from before
	// checkpoints the store keeps.
	if int64(after) >= int64(k) {
		if int64(after) >= 1<<32-1 {
			return 0, nil, fmt.Errorf("checkpoint %d: past what the manifest numbers", after)
		}
		k = uint32(after) + 1
		if _, err := tx.Archived.Update().Where(archived.IdEQ(archivedCounter)).SetSince(k).Save(ctx); err != nil {
			return 0, nil, err
		}
	}

	// In it from now on: what was added since the last one.
	if _, err := tx.Archived.Update().
		Where(archived.NamespaceNEQ(""), archived.StateIn(trail.Present, trail.Erasing), archived.SinceEQ(0)).
		SetSince(k).
		Save(ctx); err != nil {
		return 0, nil, err
	}

	// Out of it from now on: what was erased since.
	if _, err := tx.Archived.Update().
		Where(archived.NamespaceNEQ(""), archived.StateEQ(trail.Erased), archived.GoneEQ(0), archived.SinceGT(0)).
		SetGone(k).
		Save(ctx); err != nil {
		return 0, nil, err
	}

	// And what no checkpoint read back any more was in: erased before one
	// saw it, or gone before the one before this.
	if _, err := tx.Archived.Delete().
		Where(
			archived.NamespaceNEQ(""),
			archived.StateEQ(trail.Erased),
			archived.Or(archived.SinceEQ(0), archived.And(archived.GoneGT(0), archived.GoneLT(k))),
		).
		Exec(ctx); err != nil {
		return 0, nil, err
	}

	vs, err := tx.Archived.Query().Where(archivedAt(k)).All(ctx)
	if err != nil {
		return 0, nil, err
	}

	return int(k), archivedRows(vs), tx.Commit()
}

func (s trailStore) At(ctx context.Context, k int) ([]trail.Archived, error) {
	vs, err := s.db.Archived.Query().Where(archivedAt(uint32(k))).All(ctx)
	if err != nil {
		return nil, err
	}

	return archivedRows(vs), nil
}

func (s trailStore) Latest(ctx context.Context) (int, time.Time, error) {
	c, err := s.db.Archived.Get(ctx, archivedCounter)
	if ent.IsNotFound(err) {
		return 0, time.Time{}, nil
	}
	if err != nil {
		return 0, time.Time{}, err
	}

	return int(c.Since), c.DateUpdated, nil
}

// archivedAt is the rows a checkpoint was taken over: in it by then, and
// not gone by then.
func archivedAt(k uint32) predicate.Archived {
	return archived.And(
		archived.NamespaceNEQ(""),
		archived.SinceGT(0),
		archived.SinceLTE(k),
		archived.Or(archived.GoneEQ(0), archived.GoneGT(k)),
	)
}

func archivedRow(v *ent.Archived) trail.Archived {
	return trail.Archived{
		Key:       v.Id,
		Namespace: v.Namespace,
		Digest:    v.Digest,
		Intent:    v.Intent,
		Labels:    v.Labels,
		State:     v.State,
		Since:     int(v.Since),
		Gone:      int(v.Gone),
		Created:   v.DateCreated,
		Updated:   v.DateUpdated,
		Signature: trail.Signature{Key: v.SignedBy, Sig: v.Signature},
	}
}

func archivedRows(vs []*ent.Archived) []trail.Archived {
	out := make([]trail.Archived, 0, len(vs))
	for _, v := range vs {
		out = append(out, archivedRow(v))
	}

	return out
}

func (s trailStore) BlankSeals(ctx context.Context, objects []pdid.Id, forgotten func(pdid.Id) []byte) (int, error) {
	n := 0
	for page := range slices.Chunk(objects, audit1.RowsPage) {
		ids, err := s.db.RowSeal.Query().Where(rowseal.IdIn(uuids(page)...)).Ids(ctx)
		if err != nil || len(ids) == 0 {
			if err != nil {
				return n, err
			}
			continue
		}
		if forgotten == nil {
			k, err := s.db.RowSeal.Delete().Where(rowseal.IdIn(ids...)).Exec(ctx)
			n += k
			if err != nil {
				return n, err
			}
			continue
		}
		for _, id := range ids {
			if err := s.db.RowSeal.UpdateOneId(id).SetSum(forgotten(pdid.Id(id))).Exec(ctx); err != nil {
				return n, err
			}
			n++
		}
	}

	return n, nil
}

func (s trailStore) PurgeSeals(ctx context.Context, tenant pdid.Id) (int, error) {
	return s.db.RowSeal.Delete().Where(rowseal.TenantId(tenant.Uuid())).Exec(ctx)
}

// InTx is whether the client is bound to a transaction -- one it began, or
// one begun with `dialect.BeginTx` that it shares. The archive takes no
// part in it: an erasure is owed there rather than written, and every other
// act is refused (`trail.ErrInTx`).
func (s trailStore) InTx() bool { return s.db.InTx() }

func (s trailStore) Owe(ctx context.Context, objects []pdid.Id) error {
	now := time.Now()
	qs := make([]*ent.OwedCreate, 0, len(objects))
	for _, v := range objects {
		qs = append(qs, s.db.Owed.Create().
			SetId(pdid.New(OwedDomain).Uuid()).
			SetObject(v.Uuid()).
			SetHeldBy([][]byte{}).
			SetDateCreated(now))
	}
	for vs := range slices.Chunk(qs, keptTrailRows) {
		if err := s.db.Owed.CreateBulk(vs...).Exec(ctx); err != nil {
			return err
		}
	}

	return nil
}

func (s trailStore) Owed(ctx context.Context, after trail.Cursor, limit int) ([]trail.Owed, error) {
	q := s.db.Owed.Query()
	if after.Key != nil {
		id, err := cursorOf(after.Key)
		if err != nil {
			return nil, err
		}

		// After the cursor, as one comparison of the pair: an index starts the read
		// at it, where the OR it means is a filter and every page is read from the
		// first row.
		q = q.Where(func(s *sql.Selector) {
			s.Where(sql.CompositeGT([]string{s.C(owed.FieldDateCreated), s.C(owed.FieldId)}, after.Created, id))
		})
	}

	vs, err := q.Order(ent.Asc(owed.FieldDateCreated, owed.FieldId)).Limit(limit).All(ctx)
	if err != nil {
		return nil, err
	}

	out := make([]trail.Owed, 0, len(vs))
	for _, v := range vs {
		by := make([]pdid.Id, 0, len(v.HeldBy))
		for _, b := range v.HeldBy {
			if id, err := pdid.From(b); err == nil {
				by = append(by, id)
			}
		}
		out = append(out, trail.Owed{Key: v.Id, Object: pdid.Id(v.Object), Created: v.DateCreated, HeldBy: by})
	}

	return out, nil
}

func (s trailStore) Paid(ctx context.Context, keys []any) (int, error) {
	ids := make([]uuid.UUID, 0, len(keys))
	for _, k := range keys {
		id, ok := k.(uuid.UUID)
		if !ok {
			return 0, fmt.Errorf("trail: %T is not a key this store gave out", k)
		}
		ids = append(ids, id)
	}
	if len(ids) == 0 {
		return 0, nil
	}

	return s.db.Owed.Delete().Where(owed.IdIn(ids...)).Exec(ctx)
}

func (s trailStore) Kept(ctx context.Context, key any, by []pdid.Id) error {
	id, ok := key.(uuid.UUID)
	if !ok {
		return fmt.Errorf("trail: %T is not a key this store gave out", key)
	}
	bs := make([][]byte, len(by))
	for i, v := range by {
		bs[i] = v.Bytes()
	}

	return s.db.Owed.UpdateOneId(id).SetHeldBy(bs).Exec(ctx)
}

// TrailOf is a reader of the archive's documents as the messages they hold:
// what `policy.Read` and `policy.ReadTenant` are handed, and `trail.Read`,
// `trail.ReadTenant` and `trail.ReadFiles`, which check nothing.
//
//	err := policy.ReadTenant(ctx, store, tenant, pd.TrailOf(func(v *app.Audit) error {
//		...
//	}))
//
// The runtime hands over documents, because it has no `Audit` type to
// unmarshal into. This is the half that does.
//
// It opens no database, deliberately: what an archive is for is outliving
// the deployment that wrote it, and a reader that needed the deployment
// would be answering the question at the one moment nobody can.
func TrailOf(fn func(*apptest.Audit) error) func(doc []byte) error {
	return func(doc []byte) error {
		if accessDoc(doc) {
			return nil
		}

		v := &apptest.Audit{}
		if err := protojson.Unmarshal(doc, v); err != nil {
			return err
		}

		return fn(v)
	}
}

// Past is this app's past as the `past` package writes and reads it
// (payday#151): its Event and Fact, written through `next` -- the stack an
// operation writes through -- on `drv`, and read through ent on `drv`.
// `content` is the trail's (`audit.content`, `audit.digest.key`), what an
// act of the past beneath the servers is recorded with: see [Record].
//
//	drv, tx, err := dialect.BeginTx(ctx, s.drv)
//	...
//	st, err := pd.Past(s.Next(), drv, content)
//	ctx, op, err := past.Begin(ctx, st, past.Event{Subject: id, Value: moved})
//
// `next` is put on `drv` here rather than trusted to be, so that every
// write of the past is in the transaction its operation is; it answers
// an error for a stack a layer of which cannot be put on another driver,
// whose writes would go around that layer.
//
// Its writes are the only ones of Event and Fact the Audit layer lets
// through, wherever in `next` that layer is: each is marked for it, on the
// context handed to the servers and no other ([pastWrite]).
func Past(next apptest.Server, drv dialect.Driver, content audit1.Contents) (past.Store, error) {
	s, err := enttx.Rebind(next, drv)
	if err != nil {
		return nil, err
	}

	return pastStore{next: s, drv: drv, db: ent.NewClient(ent.Driver(drv)), content: content}, nil
}

type pastStore struct {
	next    apptest.Server
	drv     dialect.Driver
	db      *ent.Client
	content audit1.Contents
}

var _ past.Store = pastStore{}

// Kinds is [EventKinds].
func (pastStore) Kinds() map[string]protoreflect.MessageType { return EventKinds }

func (s pastStore) Driver() dialect.Driver { return s.drv }

// AddEvents writes each event through the Event server: an Add for one, an
// AddMany of at most a page for more. On a context marked as the past's
// write, which is what the Audit layer lets one through on.
func (s pastStore) AddEvents(ctx context.Context, vs []past.EventRow) ([]pdid.Id, error) {
	ctx = pastWriting(ctx)

	reqs := make([]*apptest.EventAddRequest, len(vs))
	for i, v := range vs {
		req := apptest.EventAddRequest_builder{
			Tenant:      apptest.TenantRef_builder{Id: v.Tenant.Bytes()}.Build(),
			Kind:        v.Kind,
			OccurredAt:  timestamppb.New(v.At),
			Reason:      v.Reason,
			DateCreated: timestamppb.New(v.Recorded),
			Value:       v.Value,
		}.Build()
		if !v.Id.IsZero() {
			req.SetId(v.Id.Bytes())
		}
		if !v.Actor.IsZero() {
			req.SetActorId(v.Actor.Bytes())
		}
		if !v.Subject.IsZero() {
			req.SetSubjectId(v.Subject.Bytes())
		}
		if !v.Cause.IsZero() {
			req.SetCauseId(v.Cause.Bytes())
		}
		if len(v.Trace) > 0 {
			req.SetTraceId(v.Trace)
		}
		reqs[i] = req
	}

	out := make([]pdid.Id, 0, len(reqs))
	if len(reqs) == 1 {
		v, err := s.next.Event().Add(ctx, reqs[0])
		if err != nil {
			return nil, err
		}
		id, err := pdid.From(v.GetId())
		if err != nil {
			return nil, err
		}

		return append(out, id), nil
	}
	for page := range slices.Chunk(reqs, bare.EventAddManyMax) {
		res, err := s.next.Event().AddMany(ctx, apptest.EventAddManyRequest_builder{Items: page}.Build())
		if err != nil {
			return nil, err
		}
		for _, v := range res.GetItems() {
			id, err := pdid.From(v.GetId())
			if err != nil {
				return nil, err
			}
			out = append(out, id)
		}
	}

	return out, nil
}

// AddFacts writes each fact through the Fact server, as [pastStore.AddEvents]
// writes events.
func (s pastStore) AddFacts(ctx context.Context, vs []past.FactRow) error {
	ctx = pastWriting(ctx)

	reqs := make([]*apptest.FactAddRequest, len(vs))
	for i, v := range vs {
		field, domain := uint32(v.Field), uint32(v.Domain)
		reqs[i] = apptest.FactAddRequest_builder{
			Tenant:      apptest.TenantRef_builder{Id: v.Tenant.Bytes()}.Build(),
			SubjectId:   v.Subject.Bytes(),
			Key:         v.Key,
			Value:       v.Value,
			FieldNumber: &field,
			Domain:      &domain,
			ValidFrom:   timestamppb.New(v.From),
			EventId:     v.Event.Bytes(),
			DateCreated: timestamppb.New(v.Recorded),
		}.Build()
	}

	if len(reqs) == 1 {
		_, err := s.next.Fact().Add(ctx, reqs[0])
		return err
	}
	for page := range slices.Chunk(reqs, bare.FactAddManyMax) {
		if _, err := s.next.Fact().AddMany(ctx, apptest.FactAddManyRequest_builder{Items: page}.Build()); err != nil {
			return err
		}
	}

	return nil
}

// Supersede is a Patch of each fact, held to the version it was read at,
// on a context marked as the past's write.
func (s pastStore) Supersede(ctx context.Context, vs []past.FactRow, at time.Time, by pdid.Id) error {
	ctx = pastWriting(ctx)

	for _, v := range vs {
		if _, err := s.next.Fact().Patch(ctx, apptest.FactPatchRequest_builder{
			Ref:          apptest.FactRef_builder{Id: v.Id.Bytes()}.Build(),
			DateUpdated:  timestamppb.New(v.Version),
			SupersededAt: timestamppb.New(at),
			SupersededBy: by.Bytes(),
		}.Build()); err != nil {
			return err
		}
	}

	return nil
}

// Events reads events through ent, by the predicates the package built.
func (s pastStore) Events(ctx context.Context, q past.Select) ([]past.EventRow, error) {
	query := s.db.Event.Query()
	for _, v := range q.Where {
		query = query.Where(predicate.Event(v))
	}
	for _, v := range q.Order {
		query = query.Order(event.OrderOption(v))
	}
	if q.Limit > 0 {
		query = query.Limit(q.Limit)
	}

	vs, err := query.All(ctx)
	if err != nil {
		return nil, err
	}

	out := make([]past.EventRow, len(vs))
	for i, v := range vs {
		r := past.EventRow{
			Id:       pdid.Id(v.Id),
			Tenant:   pdid.Id(v.TenantId),
			Kind:     v.Kind,
			At:       v.OccurredAt,
			Reason:   v.Reason,
			Trace:    v.TraceId,
			Value:    v.Value,
			Recorded: v.DateCreated,
		}
		if v.ActorId != nil {
			r.Actor = pdid.Id(*v.ActorId)
		}
		if v.SubjectId != nil {
			r.Subject = pdid.Id(*v.SubjectId)
		}
		if v.CauseId != nil {
			r.Cause = pdid.Id(*v.CauseId)
		}
		out[i] = r
	}

	return out, nil
}

// Facts reads facts through ent, by the predicates the package built.
func (s pastStore) Facts(ctx context.Context, q past.Select) ([]past.FactRow, error) {
	query := s.db.Fact.Query()
	for _, v := range q.Where {
		query = query.Where(predicate.Fact(v))
	}
	for _, v := range q.Order {
		query = query.Order(fact.OrderOption(v))
	}
	if q.Limit > 0 {
		query = query.Limit(q.Limit)
	}

	vs, err := query.All(ctx)
	if err != nil {
		return nil, err
	}

	out := make([]past.FactRow, len(vs))
	for i, v := range vs {
		r := past.FactRow{
			Id:         pdid.Id(v.Id),
			Tenant:     pdid.Id(v.TenantId),
			Subject:    pdid.Id(v.SubjectId),
			Domain:     pdid.Domain(v.Domain),
			Field:      protoreflect.FieldNumber(v.FieldNumber),
			Key:        v.Key,
			Value:      v.Value,
			From:       v.ValidFrom,
			Recorded:   v.DateCreated,
			Event:      pdid.Id(v.EventId),
			Version:    v.DateUpdated,
			Superseded: v.SupersededAt,
		}
		if v.SupersededBy != nil {
			r.SupersededBy = pdid.Id(*v.SupersededBy)
		}
		out[i] = r
	}

	return out, nil
}

// Describe is [described]: what the trail withholds of a row is what a
// fact withholds of a field.
func (pastStore) Describe(subject pdid.Id) (past.Description, bool) {
	md, secret, personal := described(subject)
	if md == nil {
		return past.Description{}, false
	}

	return past.Description{Message: md, Secret: secret, Personal: personal}, true
}

// TenantOf reads each row as a check of the rows reads it, past the wall,
// and its tenant as the recorder finds the one a write is filed under
// ([subject]): the same answer to the same question, which is whose a row is.
func (s pastStore) TenantOf(ctx context.Context, ids []pdid.Id) (map[pdid.Id]pdid.Id, error) {
	srv, err := bare.NewServer(s.db)
	if err != nil {
		return nil, err
	}

	byKind := map[pdid.Domain][]pdid.Id{}
	for _, v := range ids {
		byKind[v.Domain()] = append(byKind[v.Domain()], v)
	}

	out := map[pdid.Id]pdid.Id{}
	for _, d := range slices.Sorted(maps.Keys(byKind)) {
		for page := range slices.Chunk(byKind[d], audit1.RowsPage) {
			var rows []audit1.Live
			global := false
			switch d {
			case CellDomain:
				rows, err = rowsCell(ctx, s.db, cell.IdIn(uuids(page)...))
			case EventDomain:
				rows, err = rowsEvent(ctx, s.db, event.IdIn(uuids(page)...))
			case FactDomain:
				rows, err = rowsFact(ctx, s.db, fact.IdIn(uuids(page)...))
			case FleetDomain:
				rows, err = rowsFleet(ctx, s.db, fleet.IdIn(uuids(page)...))
				global = true
			case HolderDomain:
				rows, err = rowsHolder(ctx, s.db, holder.IdIn(uuids(page)...))
			case JointDomain:
				rows, err = rowsJoint(ctx, s.db, joint.IdIn(uuids(page)...))
			case MachineDomain:
				rows, err = rowsMachine(ctx, s.db, machine.IdIn(uuids(page)...))
			case PairingDomain:
				rows, err = rowsPairing(ctx, s.db, pairing.IdIn(uuids(page)...))
			case PulseDomain:
				rows, err = rowsPulse(ctx, s.db, pulse.IdIn(uuids(page)...))
				global = true
			case ReadingDomain:
				rows, err = rowsReading(ctx, s.db, reading.IdIn(uuids(page)...))
			case RobotDomain:
				rows, err = rowsRobot(ctx, s.db, robot.IdIn(uuids(page)...))
			case SealDomain:
				rows, err = rowsSeal(ctx, s.db, seal.IdIn(uuids(page)...))
				global = true
			case StintDomain:
				rows, err = rowsStint(ctx, s.db, stint.IdIn(uuids(page)...))
			case TallyDomain:
				rows, err = rowsTally(ctx, s.db, tally.IdIn(uuids(page)...))
			case TenantDomain:
				rows, err = rowsTenant(ctx, s.db, tenant.IdIn(uuids(page)...))
			case ThingDomain:
				rows, err = rowsThing(ctx, s.db, thing.IdIn(uuids(page)...))
				global = true
			default:
				return nil, fmt.Errorf("%s is of a kind whose tenant this app cannot say, so it is the subject of no past", page[0])
			}
			if err != nil {
				return nil, err
			}

			for _, v := range rows {
				if global {
					out[v.Object] = pdid.Nil
					continue
				}

				t, _, err := subject(ctx, srv, v.Object, v.Row, false)
				if err != nil {
					return nil, err
				}
				if t == uuid.Nil() {
					// Behind the wall and reaching no tenant -- a first hop
					// left empty -- which the wall shows to nobody: as no row.
					continue
				}
				out[v.Object] = pdid.Id(t)
			}
		}
	}

	return out, nil
}

// Redact blanks the reason of an event through ent -- an event has no
// Patch -- and puts that on the trail as `action`, in the same transaction:
// a line by whoever `ctx` is framed as, with the event's digest as it is
// now and its seal made again ([Record]).
func (s pastStore) Redact(ctx context.Context, id pdid.Id, action string) error {
	n, err := s.db.Event.Update().Where(event.IdEQ(uuid.UUID(id))).SetReason("").Save(ctx)
	if err != nil {
		return err
	}
	if n == 0 {
		return status.Error(codes.NotFound, "Event not found")
	}

	_, err = Record(ctx, s.db, s.content, action, []pdid.Id{id})
	return err
}

// PastNames is what names the people and things a sentence of this app's
// past names, as they are called when it is read (payday#151): a row of any
// entity with a name or an alias, by `header.Of(row).Title()` -- its name,
// else its alias -- read on `drv` through the wall, so that a sentence names
// nothing its reader could not read for themselves.
//
// A title read off a field the entity declares `personal` -- a holder's --
// is that person's data, and it answers the row as whose it is, which the
// `past` package puts on the access record of the call that said it. An
// identifier of a row that is gone, of one the caller may not see, or of a
// kind with nothing to be called by is named by nothing.
//
//	r := sentences.Read(ctx, pd.PastNames(drv), locale, zone)
func PastNames(drv dialect.Driver) past.Names {
	return pastNames{db: ent.NewClient(ent.Driver(drv))}
}

type pastNames struct{ db *ent.Client }

var _ past.Names = pastNames{}

// Name reads the row `id` names through the wall, and answers what it is
// called and -- where that was read off a field declared `personal` -- the
// row, as whose data saying it is.
func (n pastNames) Name(ctx context.Context, id pdid.Id) (string, []access1.Subject, error) {
	var row proto.Message
	var alias, name bool
	switch id.Domain() {
	case CellDomain:
		p, err := bare.CellNarrow(ctx, Wall(), cell.IdEQ(id.Uuid()))
		if err != nil {
			return "", nil, err
		}
		v, err := n.db.Cell.Query().Where(p).Only(ctx)
		if err != nil {
			return pastUnnamed(err)
		}
		row, alias, name = v.Proto(), false, false
	case FleetDomain:
		p, err := bare.FleetNarrow(ctx, Wall(), fleet.IdEQ(id.Uuid()))
		if err != nil {
			return "", nil, err
		}
		v, err := n.db.Fleet.Query().Where(p).Only(ctx)
		if err != nil {
			return pastUnnamed(err)
		}
		row, alias, name = v.Proto(), false, false
	case HolderDomain:
		p, err := bare.HolderNarrow(ctx, Wall(), holder.IdEQ(id.Uuid()))
		if err != nil {
			return "", nil, err
		}
		v, err := n.db.Holder.Query().Where(p).Only(ctx)
		if err != nil {
			return pastUnnamed(err)
		}
		row, alias, name = v.Proto(), true, true
	case JointDomain:
		p, err := bare.JointNarrow(ctx, Wall(), joint.IdEQ(id.Uuid()))
		if err != nil {
			return "", nil, err
		}
		v, err := n.db.Joint.Query().Where(p).Only(ctx)
		if err != nil {
			return pastUnnamed(err)
		}
		row, alias, name = v.Proto(), false, false
	case MachineDomain:
		p, err := bare.MachineNarrow(ctx, Wall(), machine.IdEQ(id.Uuid()))
		if err != nil {
			return "", nil, err
		}
		v, err := n.db.Machine.Query().Where(p).Only(ctx)
		if err != nil {
			return pastUnnamed(err)
		}
		row, alias, name = v.Proto(), false, false
	case RobotDomain:
		p, err := bare.RobotNarrow(ctx, Wall(), robot.IdEQ(id.Uuid()))
		if err != nil {
			return "", nil, err
		}
		v, err := n.db.Robot.Query().Where(p).Only(ctx)
		if err != nil {
			return pastUnnamed(err)
		}
		row, alias, name = v.Proto(), false, false
	case SealDomain:
		p, err := bare.SealNarrow(ctx, Wall(), seal.IdEQ(id.Uuid()))
		if err != nil {
			return "", nil, err
		}
		v, err := n.db.Seal.Query().Where(p).Only(ctx)
		if err != nil {
			return pastUnnamed(err)
		}
		row, alias, name = v.Proto(), false, false
	case TenantDomain:
		p, err := bare.TenantNarrow(ctx, Wall(), tenant.IdEQ(id.Uuid()))
		if err != nil {
			return "", nil, err
		}
		v, err := n.db.Tenant.Query().Where(p).Only(ctx)
		if err != nil {
			return pastUnnamed(err)
		}
		row, alias, name = v.Proto(), false, false
	case ThingDomain:
		p, err := bare.ThingNarrow(ctx, Wall(), thing.IdEQ(id.Uuid()))
		if err != nil {
			return "", nil, err
		}
		v, err := n.db.Thing.Query().Where(p).Only(ctx)
		if err != nil {
			return pastUnnamed(err)
		}
		row, alias, name = v.Proto(), false, false
	default:
		return "", nil, nil
	}

	h := header.Of(row)
	if h.Name != "" && name || h.Name == "" && h.Alias != "" && alias {
		return h.Title(), []access1.Subject{{Id: id, Tenant: h.Tenant}}, nil
	}

	return h.Title(), nil, nil
}

// pastUnnamed is a row that could not be read: named by nothing when there
// is none to read -- gone, or behind the wall -- and the error otherwise.
func pastUnnamed(err error) (string, []access1.Subject, error) {
	if ent.IsNotFound(err) {
		return "", nil, nil
	}

	return "", nil, err
}

// Pointers is [pastPointers].
func (pastStore) Pointers() []past.Pointer { return pastPointers }

// pastPointers is every column of this app's that names an event,
// `(payday.field) = {event: true}`: what the expiry asks of each event it
// would take, whether a row that stays names it.
var pastPointers = []past.Pointer{
	{Domain: EventDomain, Table: event.Table, Column: event.FieldCauseId, Own: pdpb.Own_OWN_EVENT},
	{Domain: FactDomain, Table: fact.Table, Column: fact.FieldEventId, Own: pdpb.Own_OWN_FACT},
	{Domain: FactDomain, Table: fact.Table, Column: fact.FieldSupersededBy, Own: pdpb.Own_OWN_FACT},
	{Domain: StintDomain, Table: stint.Table, Column: stint.FieldEventId, Own: pdpb.Own_OWN_UNSPECIFIED},
}

// DeleteEvents deletes the rows `ids` names through ent, a page at a time:
// Event has no Erase, and its rows leave by expiry or with their tenant.
// What it takes is put on the trail by [pastStore.Erased].
func (s pastStore) DeleteEvents(ctx context.Context, ids []pdid.Id) (int, error) {
	n := 0
	for page := range slices.Chunk(ids, audit1.RowsPage) {
		k, err := s.db.Event.Delete().Where(event.IdIn(uuids(page)...)).Exec(ctx)
		n += k
		if err != nil {
			return n, err
		}
	}

	return n, nil
}

// CountEvents counts the rows `where` takes, through ent.
func (s pastStore) CountEvents(ctx context.Context, where []func(*sql.Selector)) (int, error) {
	query := s.db.Event.Query()
	for _, v := range where {
		query = query.Where(predicate.Event(v))
	}

	return query.Count(ctx)
}

// DeleteFacts deletes the rows `ids` names through ent, a page at a time:
// Fact has no Erase, and its rows leave by expiry or with their tenant.
// What it takes is put on the trail by [pastStore.Erased].
func (s pastStore) DeleteFacts(ctx context.Context, ids []pdid.Id) (int, error) {
	n := 0
	for page := range slices.Chunk(ids, audit1.RowsPage) {
		k, err := s.db.Fact.Delete().Where(fact.IdIn(uuids(page)...)).Exec(ctx)
		n += k
		if err != nil {
			return n, err
		}
	}

	return n, nil
}

// CountFacts counts the rows `where` takes, through ent.
func (s pastStore) CountFacts(ctx context.Context, where []func(*sql.Selector)) (int, error) {
	query := s.db.Fact.Query()
	for _, v := range where {
		query = query.Where(predicate.Fact(v))
	}

	return query.Count(ctx)
}

// Erased puts on the trail the rows `ids`, deleted beneath the servers, as the
// act `action` ([RecordErased]): by whoever `ctx` is framed as, filed under
// its tenant, in the same transaction.
func (s pastStore) Erased(ctx context.Context, action string, ids []pdid.Id) error {
	_, err := RecordErased(ctx, s.db, s.content, action, ids)
	return err
}

// PastIn is where the past's expiry does a tenant's (payday#151): `f`, in a
// transaction of its own on `drv`, with the context framed as the
// deployment's work in `tenant` -- nobody's, and of that tenant alone -- and a
// store of the past through `ungated` put on that transaction. Committed when
// `f` answers nil, and rolled back otherwise. What `past.Expirer.In` is.
//
// `ungated` is the stack with no wall, as for every sweep: an expiry is the
// deployment acting on itself, and nobody's in the tenant. Never one a caller
// reaches.
//
// What `f` is handed writes the past through the store and no other way:
// the store marks what it hands the servers, and the context `f` is given
// is no write of the past's, so a row `f` writes by hand with it is refused
// as any other is ([pastWrite]).
func PastIn(ungated apptest.Server, drv dialect.Driver, content audit1.Contents) func(ctx context.Context, tenant pdid.Id, f func(ctx context.Context, s past.Store) error) error {
	return func(ctx context.Context, tenant pdid.Id, f func(ctx context.Context, s past.Store) error) error {
		ctx = frame.Into(ctx, frame.New(pdid.Nil, tenant, frame.Grant{}).WithScope(frame.Only(tenant)))

		tdrv, tx, err := dialect.BeginTx(ctx, drv)
		if err != nil {
			return err
		}
		defer tx.Rollback()

		s, err := Past(ungated, tdrv, content)
		if err != nil {
			return err
		}
		if err := f(ctx, s); err != nil {
			return err
		}

		return tx.Commit()
	}
}

// PastTenants is every tenant with a past, a page of at most `limit` after
// `after` in the order of their identifiers: what `past.Expirer.Tenants` is.
// One seek per tenant, the next `tenant_id` of the Event after the last, which
// its index on the tenant answers without reading the rows between. A fact
// names the event that wrote it, which stays while it does, so a tenant with
// facts has events.
func PastTenants(db *ent.Client) func(ctx context.Context, after pdid.Id, limit int) ([]pdid.Id, error) {
	return func(ctx context.Context, after pdid.Id, limit int) ([]pdid.Id, error) {
		out := []pdid.Id{}
		last := after.Uuid()
		for len(out) < limit {
			v, err := db.Event.Query().
				Where(predicate.Event(sql.FieldGT(event.FieldTenantId, last))).
				Order(ent.Asc(event.FieldTenantId)).
				First(ctx)
			switch {
			case ent.IsNotFound(err):
				return out, nil
			case err != nil:
				return out, err
			}

			out = append(out, pdid.Id(v.TenantId))
			last = v.TenantId
		}

		return out, nil
	}
}

// personal is what a message holding a field declared `personal` is to the
// access record: its key, those fields, and how to read the tenant it is in.
type personal struct {
	key    protoreflect.FieldDescriptor
	fields []protoreflect.FieldDescriptor
	tenant func(protoreflect.Message) pdid.Id
}

// carries answers whether `m` holds a value of any of the fields.
func (p personal) carries(m protoreflect.Message) bool {
	for _, fd := range p.fields {
		if m.Has(fd) {
			return true
		}
	}

	return false
}

// personals is every message that holds a field declared `personal`, by its
// full name; refs is the reference to each that a request names a row by,
// and the field of it that is the row's key.
var (
	personals = map[protoreflect.FullName]personal{}
	refs      = map[protoreflect.FullName]protoreflect.FieldDescriptor{}
)

func init() {
	{
		md := (&apptest.Event{}).ProtoReflect().Descriptor()
		fs := md.Fields()
		personals[md.FullName()] = personal{
			key: fs.ByNumber(1),
			fields: []protoreflect.FieldDescriptor{
				fs.ByNumber(11),
			},
			tenant: func(m protoreflect.Message) pdid.Id {
				return accessKeyOf(m.Get(fs.ByName("tenant")).Message())
			},
		}
		r := (&apptest.EventRef{}).ProtoReflect().Descriptor()
		refs[r.FullName()] = r.Fields().ByName("id")
	}
	{
		md := (&apptest.Holder{}).ProtoReflect().Descriptor()
		fs := md.Fields()
		personals[md.FullName()] = personal{
			key: fs.ByNumber(1),
			fields: []protoreflect.FieldDescriptor{
				fs.ByNumber(4),
				fs.ByNumber(5),
				fs.ByNumber(6),
				fs.ByNumber(7),
				fs.ByNumber(8),
				fs.ByNumber(9),
			},
			tenant: func(m protoreflect.Message) pdid.Id {
				return accessKeyOf(m.Get(fs.ByName("tenant")).Message())
			},
		}
		r := (&apptest.HolderRef{}).ProtoReflect().Descriptor()
		refs[r.FullName()] = r.Fields().ByName("id")
	}
	{
		md := (&apptest.Machine{}).ProtoReflect().Descriptor()
		fs := md.Fields()
		personals[md.FullName()] = personal{
			key: fs.ByNumber(1),
			fields: []protoreflect.FieldDescriptor{
				fs.ByNumber(24),
			},
			tenant: func(m protoreflect.Message) pdid.Id {
				return accessKeyOf(m.Get(fs.ByName("tenant")).Message())
			},
		}
		r := (&apptest.MachineRef{}).ProtoReflect().Descriptor()
		refs[r.FullName()] = r.Fields().ByName("id")
	}
	{
		md := (&apptest.Robot{}).ProtoReflect().Descriptor()
		fs := md.Fields()
		personals[md.FullName()] = personal{
			key: fs.ByNumber(1),
			fields: []protoreflect.FieldDescriptor{
				fs.ByNumber(32),
			},
			tenant: func(m protoreflect.Message) pdid.Id {
				return accessKeyOf(m.Get(fs.ByName("tenant")).Message())
			},
		}
		r := (&apptest.RobotRef{}).ProtoReflect().Descriptor()
		refs[r.FullName()] = r.Fields().ByName("id")
	}
}

// Subjects is whose personal data `m` carries (payday#111): the key of every
// message in it that holds a field declared `personal`, and the tenant that
// message names -- what the access record's interceptor is handed as
// `access.Config.Subjects`.
func Subjects(m proto.Message) []access1.Subject {
	out := []access1.Subject{}
	if m != nil {
		subjectsIn(m.ProtoReflect(), true, &out)
	}

	return out
}

// SubjectRefs is whose rows the request `m` names by key: what a call that
// was refused carried, having no answer -- `access.Config.Refs`.
func SubjectRefs(m proto.Message) []access1.Subject {
	out := []access1.Subject{}
	if m != nil {
		refsIn(m.ProtoReflect(), true, &out)
	}

	return out
}

// envelopes are the fields payday packs a message into an `Any` in: a
// batch's operations and answers, and a watch's events. What one holds is
// read unpacked, and nothing inside it is unpacked again. An `Any` anywhere
// else is the app's own data, which no declaration describes: it is passed
// over, and a tenant it names is never taken for whose a row is.
var envelopes = map[protoreflect.FullName]bool{
	(&pdpb.Op{}).ProtoReflect().Descriptor().Fields().ByName("request").FullName():            true,
	(&pdpb.BatchResponse{}).ProtoReflect().Descriptor().Fields().ByName("results").FullName(): true,
	(&pdpb.WatchEvent{}).ProtoReflect().Descriptor().Fields().ByName("value").FullName():      true,
	(&pdpb.WatchEvent{}).ProtoReflect().Descriptor().Fields().ByName("previous").FullName():   true,
}

// unpacked is what the `Any` the field `fd` holds carries, when `fd` is an
// envelope and unpacking is still allowed; nil otherwise.
func unpacked(fd protoreflect.FieldDescriptor, m protoreflect.Message, unpack bool) protoreflect.Message {
	if !unpack || !envelopes[fd.FullName()] {
		return nil
	}
	v, ok := m.Interface().(*anypb.Any)
	if !ok {
		return nil
	}
	u, err := v.UnmarshalNew()
	if err != nil {
		return nil
	}

	return u.ProtoReflect()
}

// isAny answers whether `m` is an `Any`, which is read only as an envelope.
func isAny(m protoreflect.Message) bool {
	_, ok := m.Interface().(*anypb.Any)
	return ok
}

func subjectsIn(m protoreflect.Message, unpack bool, out *[]access1.Subject) {
	if !m.IsValid() || isAny(m) {
		return
	}
	if p, ok := personals[m.Descriptor().FullName()]; ok && p.carries(m) {
		if id := accessIdOf(m.Get(p.key).Bytes()); !id.IsZero() {
			v := access1.Subject{Id: id}
			if p.tenant != nil {
				v.Tenant = p.tenant(m)
			}
			*out = append(*out, v)
		}
	}

	m.Range(func(fd protoreflect.FieldDescriptor, v protoreflect.Value) bool {
		eachMessage(fd, v, func(m protoreflect.Message) {
			if u := unpacked(fd, m, unpack); u != nil {
				subjectsIn(u, false, out)
				return
			}
			subjectsIn(m, unpack, out)
		})
		return true
	})
}

func refsIn(m protoreflect.Message, unpack bool, out *[]access1.Subject) {
	if !m.IsValid() || isAny(m) {
		return
	}
	if fd, ok := refs[m.Descriptor().FullName()]; ok && fd != nil && m.Has(fd) {
		if id := accessIdOf(m.Get(fd).Bytes()); !id.IsZero() {
			*out = append(*out, access1.Subject{Id: id})
		}
	}

	m.Range(func(fd protoreflect.FieldDescriptor, v protoreflect.Value) bool {
		eachMessage(fd, v, func(m protoreflect.Message) {
			if u := unpacked(fd, m, unpack); u != nil {
				refsIn(u, false, out)
				return
			}
			refsIn(m, unpack, out)
		})
		return true
	})
}

// eachMessage calls `fn` for every message the field `fd` holds in `v`.
func eachMessage(fd protoreflect.FieldDescriptor, v protoreflect.Value, fn func(protoreflect.Message)) {
	switch {
	case fd.IsList():
		if fd.Message() == nil {
			return
		}
		l := v.List()
		for i := range l.Len() {
			fn(l.Get(i).Message())
		}
	case fd.IsMap():
		if fd.MapValue().Message() == nil {
			return
		}
		v.Map().Range(func(_ protoreflect.MapKey, v protoreflect.Value) bool {
			fn(v.Message())
			return true
		})
	case fd.Message() != nil:
		fn(v.Message())
	}
}

// accessIdOf is an identifier as a row holds one, and zero for bytes that
// are none.
func accessIdOf(b []byte) pdid.Id {
	v, err := pdid.From(b)
	if err != nil {
		return pdid.Nil
	}

	return v
}

// accessKeyOf is the key of the row a message names by its first field, as
// an edge holds the row it points at, and zero for none.
func accessKeyOf(m protoreflect.Message) pdid.Id {
	if !m.IsValid() {
		return pdid.Nil
	}
	fd := m.Descriptor().Fields().ByNumber(1)
	if fd == nil || fd.Kind() != protoreflect.BytesKind {
		return pdid.Nil
	}

	return accessIdOf(m.Get(fd).Bytes())
}

// AccessSink writes rows of the access record (payday#111): what an app
// hands its `access.Writer` as `Sink`.
//
//	w := &access.Writer{Sink: pd.AccessSink(db)}
func AccessSink(db *ent.Client) func(context.Context, []access1.Record) error {
	return func(ctx context.Context, rs []access1.Record) error {
		return writeAccess(ctx, db, rs)
	}
}

// writeAccess writes rows of the access record through `db`, a statement for
// every few hundred.
func writeAccess(ctx context.Context, db *ent.Client, rs []access1.Record) error {
	qs := make([]*ent.AccessCreate, 0, len(rs))
	for _, r := range rs {
		id := r.Id
		if id.IsZero() {
			id = pdid.New(AccessDomain)
		}

		// Never nil, for the reason on [notNull].
		value := []byte{}
		if r.Detail != nil {
			b, err := proto.Marshal(r.Detail)
			if err != nil {
				return err
			}
			value = notNull(b)
		}
		subjects := make([][]byte, len(r.Subjects))
		for i, v := range r.Subjects {
			subjects[i] = v.Bytes()
		}

		qs = append(qs, db.Access.Create().
			SetId(id.Uuid()).
			SetTenantId(r.Tenant.Uuid()).
			SetActorId(r.Actor.Uuid()).
			SetActorTenantId(r.ActorTenant.Uuid()).
			SetTraceId(notNull(r.Trace)).
			SetAction(r.Action).
			SetKind(string(r.Kind)).
			SetResult(r.Result).
			SetDateCreated(r.At).
			SetValue(value).
			SetDomain(uint32(AccessDomain)).
			SetSubjects(subjects).
			SetSubjectCount(uint32(r.Count)))
	}

	for vs := range slices.Chunk(qs, 500) {
		if err := db.Access.CreateBulk(vs...).Exec(ctx); err != nil {
			return fmt.Errorf("write the access record: %w", err)
		}
	}

	return nil
}

// AccessRecorder is the recorder that puts a write's row of the access
// record in the write's own transaction (payday#111): one of the recorders
// an app hands its servers, beside `Recorder`.
//
//	rec := bare.Recorders{pd.Recorder(content), pd.AccessRecorder()}
//
// It is told of every write of the call the interceptor put in the context,
// and writes a row at each commit of the data the call's writes wrote that
// no row says yet. Where the transaction keeps nothing, it writes the row
// as the write is made, in the write's transaction all the same: what holds
// the write holds its record, and a write whose row cannot be written is
// refused with it. Either way the call says the row once it has answered
// (`access.Call.Settle`); what the call showed is the interceptor's to
// record.
func AccessRecorder() bare.Recorder { return accessRecorder{} }

type accessRecorder struct{}

// accessKept is what a transaction keeps for a call that writes in it: that
// the call's row is written at its commit.
type accessKept struct{ call *access1.Call }

// Snapshots asks for the rows a write of a kind that holds anybody's personal
// data left and erased, which are what say whose it was.
func (accessRecorder) Snapshots(method string) bare.SnapshotOptions {
	switch method {
	case apptest.EventService_Add_FullMethodName,
		apptest.EventService_AddMany_FullMethodName,
		apptest.HolderService_Add_FullMethodName,
		apptest.HolderService_Patch_FullMethodName,
		apptest.HolderService_Apply_FullMethodName,
		apptest.MachineService_Add_FullMethodName,
		apptest.MachineService_Patch_FullMethodName,
		apptest.MachineService_Apply_FullMethodName,
		apptest.RobotService_Add_FullMethodName,
		apptest.RobotService_AddMany_FullMethodName,
		apptest.RobotService_Patch_FullMethodName,
		apptest.RobotService_Apply_FullMethodName:
		return bare.SnapshotOptions{Value: true}
	case apptest.HolderService_Erase_FullMethodName,
		apptest.MachineService_Erase_FullMethodName,
		apptest.RobotService_Erase_FullMethodName:
		return bare.SnapshotOptions{Previous: true}
	}

	return bare.SnapshotOptions{}
}

func (accessRecorder) Record(ctx context.Context, s bare.Server, c bare.Change) error {
	call, ok := access1.Of(ctx)
	if !ok {
		return nil
	}

	key, err := audit1.Identifier(c.Key)
	if err != nil {
		return err
	}

	written := slices.Concat(Subjects(c.Previous), Subjects(c.Value))
	if md, _, personal := described(key); len(written) == 0 && touches(c.Patch, md, personal) {
		written = []access1.Subject{{Id: key}}
	}
	call.Wrote(written...)

	db := s.Store.Db
	k, ok := dialect.KeepOf(db.Driver())
	if !ok {
		// Nothing waits for a commit here: written now, in the write's
		// transaction, which takes the row along if it goes.
		now := call.Unkept(written...)
		if len(now) == 0 {
			return nil
		}

		d := pdpb.AccessDetail_builder{Address: call.Address()}.Build()
		if err := writeAccess(ctx, db, access1.Records(ctx, call.Method(), access1.Write, "ok", now, d, time.Now())); err != nil {
			return err
		}

		call.Kept(now...)
		return nil
	}

	k.Value(accessKept{call}, func() any {
		k.BeforeCommit(func(at context.Context) error {
			wrote, _ := call.Unsaid()
			if len(wrote) == 0 {
				return nil
			}

			d := pdpb.AccessDetail_builder{Address: call.Address()}.Build()
			rs := access1.Records(ctx, call.Method(), access1.Write, "ok", wrote, d, time.Now())
			if err := writeAccess(at, db, rs); err != nil {
				return err
			}

			// Kept, not said: the commit these rows are written ahead of
			// may still be refused, and takes them along if it is.
			call.Kept(wrote...)
			return nil
		})
		return struct{}{}
	})

	return nil
}

// touches answers whether the patch `p` set or cleared any of `fields`.
func touches(p *patchpb.Patch, md protoreflect.MessageDescriptor, fields []protoreflect.FieldDescriptor) bool {
	if p == nil || md == nil {
		return false
	}
	for _, n := range audit1.FieldsOf(p, md) {
		for _, fd := range fields {
			if uint32(fd.Number()) == n {
				return true
			}
		}
	}

	return false
}

// AccessOf is a reader of the archive's documents that hands over the
// access record's rows as the messages they are, and passes over the
// trail's: what `policy.Read` and `policy.ReadTenant` are handed for them.
// [TrailOf] is the other half, and passes over these.
func AccessOf(fn func(*apptest.Access) error) func(doc []byte) error {
	return func(doc []byte) error {
		if !accessDoc(doc) {
			return nil
		}

		v := &apptest.Access{}
		if err := protojson.Unmarshal(doc, v); err != nil {
			return err
		}

		return fn(v)
	}
}

// accessDoc answers whether an archived document is a row of the access
// record, which its domain says.
func accessDoc(doc []byte) bool {
	var h struct {
		Domain uint32 `json:"domain"`
	}

	return json.Unmarshal(doc, &h) == nil && h.Domain == uint32(AccessDomain)
}

// Cost is how many calls a request counts as: an AddMany is one for each of
// its items -- the Add each stands for -- and every other call is one.
//
// It is what the limit charges a call, and an operation of a batch, and
// what the rows a batch asks to write are counted by. [Batch] is given it
// when its guard says nothing; the interceptor is handed it:
//
//	WithUnary(grpcx.LimitUnary(c.Server.Limiter(), gate.ByTenant(), pd.Cost))
//
// An app that weighs RPCs of its own writes a Cost that asks this one for
// the rest.
func Cost(method string, req any) int {
	switch method {
	case apptest.EventService_AddMany_FullMethodName:
		if v, ok := req.(*apptest.EventAddManyRequest); ok {
			return max(len(v.GetItems()), 1)
		}
	case apptest.FactService_AddMany_FullMethodName:
		if v, ok := req.(*apptest.FactAddManyRequest); ok {
			return max(len(v.GetItems()), 1)
		}
	case apptest.ReadingService_AddMany_FullMethodName:
		if v, ok := req.(*apptest.ReadingAddManyRequest); ok {
			return max(len(v.GetItems()), 1)
		}
	case apptest.RobotService_AddMany_FullMethodName:
		if v, ok := req.(*apptest.RobotAddManyRequest); ok {
			return max(len(v.GetItems()), 1)
		}
	}

	return 1
}

var _ grpcx.Cost = Cost

// Batch answers with the server that runs several writes as one
// transaction.
//
// The guard is required and there is no default for it. Everything payday
// enforces by method name is enforced against `BatchService/Do` and not
// against what it carries, so a batch built without one is a way past all
// of it -- a caller whose credential allows one method wraps whatever they
// like in a batch, and the trail records that it was allowed.
//
//	b, err := pd.Batch(s.Walled, s.Drv, c.Server.Guard(policy))
//
// The guard comes from the configuration rather than being written out,
// which is what keeps it saying the same thing the interceptors say. Two
// places deciding what is closed will disagree, and the direction they
// disagree in is the one where the batch allows more.
//
// The driver is passed rather than taken from the server, because the
// transaction is begun on it and a `*ent.Client` does not hand out the
// driver it was built with. The app has one: it is what it built the client
// from.
func Batch(s apptest.Server, drv dialect.Driver, guard batch.Guard) (pdpb.BatchServiceServer, error) {
	if guard.IsZero() {
		// Nobody filled it in. It is the zero value and not a judgement about
		// how open the deployment is: `config.ServerConfig.Guard` always sets
		// how a caller is counted, so a deployment that closes nothing and
		// limits nothing still comes through here with something in it.
		//
		// Refused rather than served open, because served open is a privilege
		// escalation and the way it would be found is somebody reading the
		// wiring and noticing what is not there.
		return nil, batch.ErrNoGuard
	}

	// What an operation costs is the schema's to say -- an AddMany is as many
	// calls as its items -- and nothing the configuration knows. So a guard
	// that says nothing of it is given this app's ([Cost]).
	if guard.Cost == nil {
		guard.Cost = Cost
	}

	return batchServer{s: s, drv: drv, guard: guard}, nil
}

type batchServer struct {
	pdpb.UnimplementedBatchServiceServer

	s     apptest.Server
	drv   dialect.Driver
	guard batch.Guard
}

// Do runs every operation in one transaction.
//
// The transaction is opened here and the whole stack is put on it, so the
// layers each operation goes through are the same objects with the same
// rules -- the wall still narrows, the trail is still written, the outbox
// still gets its row. What changes is only which driver they are talking
// to.
//
// Nothing is published until it commits. The watch recorder remembers into
// the context and the interceptor publishes once this handler has answered,
// which is after the commit -- so a batch arrives at a subscriber as one
// event holding every change, which is what it was.
func (b batchServer) Do(ctx context.Context, req *pdpb.BatchRequest) (*pdpb.BatchResponse, error) {
	ops := req.GetOps()
	if err := b.guard.Check(len(ops)); err != nil {
		return nil, err
	}

	// What each operation asks for, as the message its method takes, and what
	// it costs -- an AddMany is as many rows as its items. A batch that asks
	// to write more rows than one transaction may is refused here, before
	// anything is charged or written: it is one transaction however many
	// operations it is said in.
	in := make([]proto.Message, len(ops))
	costs := make([]int, len(ops))
	rows := 0
	for i, op := range ops {
		v, err := unpack(op)
		if err != nil {
			return nil, batch.Failed(i, op.GetMethod(), err)
		}

		in[i], costs[i] = v, b.guard.CostOf(op.GetMethod(), v)
		rows += costs[i]
	}
	if err := b.guard.CheckRows(rows); err != nil {
		return nil, err
	}

	// Every rule for every operation, before anything is written. The
	// transaction would undo the work of a batch refused halfway, but the
	// work and the locks it took are real -- and a rate limiter that had
	// already counted the first seven would charge for a batch that never
	// happened. Each is charged what it costs, as a call of it would be.
	cs := make([]context.Context, len(ops))
	for i, op := range ops {
		c, err := b.guard.Allow(ctx, op.GetMethod(), costs[i])
		if err != nil {
			return nil, batch.Failed(i, op.GetMethod(), err)
		}

		cs[i] = c
	}

	drv, tx, err := dialect.BeginTx(ctx, b.drv)
	if err != nil {
		return nil, err
	}

	s, err := enttx.Rebind(b.s, drv)
	if err != nil {
		tx.Rollback()
		return nil, err
	}

	vs := make([]*anypb.Any, len(ops))
	for i, op := range ops {
		v, err := dispatch(cs[i], s, op.GetMethod(), in[i])
		if err != nil {
			tx.Rollback()
			return nil, batch.Failed(i, op.GetMethod(), err)
		}

		vs[i] = v
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}

	return pdpb.BatchResponse_builder{Results: vs}.Build(), nil
}

// unpack is the request an operation carries, as exactly the message its
